<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo;
class MessageReport extends Model { protected $fillable=['message_id','reported_by','reason','description','status','reviewed_by','reviewed_at']; protected function casts():array{return ['reviewed_at'=>'datetime'];} public function message():BelongsTo{return $this->belongsTo(Message::class)->withTrashed();} public function reporter():BelongsTo{return $this->belongsTo(User::class,'reported_by');} public function reviewer():BelongsTo{return $this->belongsTo(User::class,'reviewed_by');} }
